      let cuerpo = '';
      if (s2 === 'atributos') cuerpo = '<div class="fila" style="align-items:center"><h2 style="margin:0;flex:1">Atributos</h2>' + (gestor ? '<button class="primario" id="aNuevo">+ Crear atributo</button>' : '') + '</div><table style="margin-top:8px"><tr><th>Nombre</th><th>Tipo</th><th>Descripción</th><th>Norma de nomenclatura</th><th></th></tr>' + ATR_SISTEMA.map(([n, t, d]) => '<tr><td>⋮ ' + esc(n) + '</td><td class="pista">' + esc(t) + '</td><td class="pista">' + esc(d) + '</td><td class="pista">' + (['Código de estado', 'Revisión', 'Parte designada'].includes(n) ? (cfg.normas || []).map(x => esc(x.nombre)).join(', ') : '—') + '</td><td></td></tr>').join('') + A.map((a, i) => '<tr><td>⋮ <b>' + esc(a.nombre) + '</b></td><td>' + esc(a.tipo === 'lista' ? 'Lista desplegable' : a.tipo === 'texto' ? 'Campo de texto' : a.tipo) + '</td><td class="pista">' + esc(a.descripcion) + (a.valores && a.valores.length ? ' <span class="pista">(' + esc(a.valores.slice(0, 6).join(', ')) + (a.valores.length > 6 ? '…' : '') + ')</span>' : '') + '</td><td class="pista">' + ((cfg.normas || []).filter(x => x.campos.some(c => c.nombre.toLowerCase() === a.nombre.toLowerCase())).map(x => esc(x.nombre)).join(', ') || '—') + '</td><td>' + (gestor ? '<button class="mini" data-ae="' + i + '">Editar</button><button class="mini peligro" data-ax="' + i + '">Quitar</button>' : '') + '</td></tr>').join('') + '</table><div class="pista" style="margin-top:6px">Mostrando ' + (ATR_SISTEMA.length + A.length) + ' atributos (' + ATR_SISTEMA.length + ' del sistema, ' + A.length + ' personalizados).</div>';
      else if (s2 === 'etiqueta') cuerpo = '<h2>Etiqueta de revisión</h2><p class="pista">Formato del código de revisión que se espera al final del nombre. P## = P01, P02… (trabajo en progreso / compartido); C## = C01… (contractual, al publicar). Las normas de nomenclatura (Conformidad) pueden exigirlo o no.</p><div class="fila" style="align-items:flex-end"><div><label>Formato</label><input id="erF" value="' + esc(er.formato || 'P##') + '" style="width:120px"' + (gestor ? '' : ' disabled') + '></div><div style="flex:1"><label>Descripción</label><input id="erD" value="' + esc(er.descripcion || '') + '"' + (gestor ? '' : ' disabled') + '></div>' + (gestor ? '<button id="erOk">Guardar</button>' : '') + '</div>';
