        app.querySelectorAll('[data-nx]').forEach(b => b.onclick = async () => { if (!(await N.confirma('¿Quitar la norma?', 'Las carpetas que la usaban pasan a heredar.', 'Quitar', true))) return; try { await api('/api/proyectos/' + pid + '/normas/' + b.dataset.nx, { method: 'DELETE' }); vistaConfigArchivos(pid, pestana); } catch (e) { N.toast(esc(e.message), 'mal'); } });
