        const du = document.getElementById('duOk'); if (du) du.onclick = async () => { try { const r = await api('/api/proyectos/' + pid + '/duplicados', { json: { carpetas: carpetasDu, atributos: [...app.querySelectorAll('.duA:checked')].map(x => x.value) } }); document.getElementById('duRes').innerHTML = r.grupos.length ? '<div class="pista">' + r.grupos.length + ' grupo(s) de duplicados entre ' + r.revisados + ' archivos.</div>' + r.grupos.map(g => '<div class="tarjeta" style="margin-top:6px"><b class="mono">' + esc(g.clave.replace(/\|/g, ' · ')) + '</b><table>' + g.contenedores.map(c => '<tr><td class="mono"><a href="#/p/' + pid + '/c/' + c.id + '">' + esc(c.archivo || c.nombre) + '</a></td><td class="pista">' + esc(c.carpeta) + '</td><td>' + estado(c.estado) + '</td><td>V' + c.version + '</td></tr>').join('') + '</table></div>').join('') : '<div class="aviso verde">Sin duplicados entre ' + r.revisados + ' archivos.</div>'; } catch (e) { aviso(document.getElementById('duRes'), e); } };
